function parseCsvLine(line) {
  var result = [];
  var current = "";
  var inQuotes = false;
  for (var ci = 0; ci < line.length; ci++) {
    var ch = line.charAt(ci);
    if (inQuotes) {
      if (ch === '"' && ci + 1 < line.length && line.charAt(ci + 1) === '"') {
        current += '"';
        ci++;
      } else if (ch === '"') {
        inQuotes = false;
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        result.push(current);
        current = "";
      } else {
        current += ch;
      }
    }
  }
  result.push(current);
  return result;
}
